// === GENERADOR DE CONSULTAS PARA SERPER ===
// 1 credito = 1 query con num<=10. num entre 11 y 100 cuesta 2 creditos.
// OJO: Google retiro el parametro num=100 a finales de 2025. Antes de subir num,
// corre una prueba y cuenta cuantos organic realmente regresan.

const f = $input.first().json;

const puesto    = String(f['Puesto'] || '').trim();
const ciudad    = String(f['Ciudad'] || '').trim();
const kwEmpresa = String(f['Palabras clave empresa'] || '')
                    .split(',').map(s => s.trim()).filter(Boolean);
const paginas   = Math.max(1, Math.min(10, Number(f['Paginas por consulta']) || 3));

// Variantes: la base siempre, mas una por keyword de industria/empresa
const variantes = [`"${puesto}" "${ciudad}"`];
for (const kw of kwEmpresa) {
  variantes.push(`"${puesto}" "${ciudad}" "${kw}"`);
}

const out = [];
for (const v of variantes) {
  for (let p = 1; p <= paginas; p++) {
    out.push({ json: {
      q: `site:linkedin.com/in ${v}`,
      gl: 'mx',
      hl: 'es',
      num: 10,      // subir a 100 SOLO si la prueba confirma que Serper los entrega
      page: p,
      _puesto: puesto,
      _ciudad: ciudad
    }});
  }
}

return out;

// === PARSEO + DEDUP + SCORING ===
// El title de Google suele venir como: "Nombre - Puesto - Empresa | LinkedIn"
// pero NO siempre: headlines personalizados y truncados rompen el patron.
// Por eso marcamos parseo_ok y no descartamos por formato.

const objetivo = String($('Generar consultas').first().json._puesto || '');

const norm = s => String(s || '')
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '');

const tokens = norm(objetivo).split(/\s+/).filter(t => t.length > 3);

const vistos = new Set();
const out = [];

for (const item of $input.all()) {
  const organic = item.json.organic || [];

  for (const r of organic) {
    let url = String(r.link || '').split('?')[0].replace(/\/+$/, '');
    if (!/linkedin\.com\/in\//i.test(url)) continue;
    if (vistos.has(url)) continue;
    vistos.add(url);

    const limpio = String(r.title || '').replace(/\s*[|\-\u2013]\s*LinkedIn.*$/i, '').trim();
    const partes = limpio.split(/\s+-\s+/).map(s => s.trim()).filter(Boolean);

    const nombre  = partes[0] || '';
    const puesto  = partes[1] || '';
    const empresa = partes.slice(2).join(' - ');

    const texto = norm(`${puesto} ${r.snippet || ''}`);
    const hits  = tokens.filter(t => texto.includes(t)).length;
    const score = tokens.length ? hits / tokens.length : 0;

    out.push({ json: {
      nombre,
      puesto,
      empresa,
      url,
      snippet: String(r.snippet || ''),
      parseo_ok: partes.length >= 3,
      score: Number(score.toFixed(2)),
      califica: score >= 0.5 && partes.length >= 2,
      fuente: 'serper',
      fecha: new Date().toISOString().slice(0, 10)
    }});
  }
}

return out;

// === LOTES PARA APIFY ===
// run-sync-get-dataset-items corta a los 300s. Lotes de 50 dejan margen.
// Si tu actor es lento, baja a 25.

const TAM = 50;

const items = $input.all().map(i => i.json);
const lotes = [];

for (let i = 0; i < items.length; i += TAM) {
  const slice = items.slice(i, i + TAM);
  lotes.push({ json: {
    profileUrls: slice.map(x => x.url),
    _meta: slice,
    _lote: (i / TAM) + 1,
    _total_lotes: Math.ceil(items.length / TAM)
  }});
}

return lotes;

// === APLANAR RESPUESTA DE APIFY + MERGE CON LO DE SERPER ===
// Los nombres de campo cambian entre actors. Los fallbacks cubren
// las convenciones mas comunes; ajusta tras tu primera corrida real.

const byUrl = {};
for (const l of $('Lotes para Apify').all()) {
  for (const m of (l.json._meta || [])) byUrl[m.url] = m;
}

const out = [];

for (const item of $input.all()) {
  const j = item.json;
  const perfiles = Array.isArray(j) ? j
                 : Array.isArray(j.items) ? j.items
                 : [j];

  for (const p of perfiles) {
    if (!p || typeof p !== 'object') continue;

    const url = String(p.linkedinUrl || p.url || p.profileUrl || p.publicIdentifier || '')
                  .split('?')[0].replace(/\/+$/, '');
    if (!url) continue; // respuesta de error o forma inesperada, no escribir fila vacia
    const base = byUrl[url] || {};

    out.push({ json: {
      url:            url || base.url || '',
      nombre:         p.fullName || p.name || base.nombre || '',
      titular:        p.headline || '',
      puesto_actual:  p.jobTitle || p.currentPosition || base.puesto || '',
      empresa_actual: p.companyName || p.company || base.empresa || '',
      empresa_url:    p.companyWebsite || p.companyLinkedinUrl || '',
      industria:      p.companyIndustry || p.industry || '',
      tam_empresa:    p.companySize || p.employeeCount || '',
      ubicacion:      p.location || p.addressWithCountry || base.ciudad || '',
      email:          p.email || '',
      seguidores:     p.followers || p.connections || '',
      score:          base.score ?? '',
      fuente:         'serper+apify',
      fecha:          new Date().toISOString().slice(0, 10)
    }});
  }
}

return out;
